// Turns tokens/*.json into every format a consumer needs. No dependencies, so
// a fresh clone builds with nothing but Node.
//
//   node scripts/build.mjs          write the generated files
//   node scripts/build.mjs --check  fail if any generated file is stale
//
// The generated files are committed, because consumers install the packed
// tarball and never run a build step of their own.

import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (p) => JSON.parse(readFileSync(join(root, p), "utf8"));

export const brand = read("tokens/brand.json");
export const themes = readdirSync(join(root, "tokens/themes"))
  .filter((f) => f.endsWith(".json"))
  .sort()
  .map((f) => ({ id: f.replace(/\.json$/, ""), ...read(`tokens/themes/${f}`) }));

const HEADER = "Generated by scripts/build.mjs from tokens/ — edit the JSON, not this file.";

/** Flatten brand.json into [path[], value] pairs, skipping $comment keys. */
function flatten(obj, path = []) {
  return Object.entries(obj).flatMap(([k, v]) => {
    if (k.startsWith("$")) return [];
    return typeof v === "object" ? flatten(v, [...path, k]) : [[[...path, k], v]];
  });
}

/** color.navy.800 -> --sl-navy-800; text.hero -> --sl-text-hero. */
const cssName = (path) => `--sl-${(path[0] === "color" ? path.slice(1) : path).join("-")}`;

export const primitives = flatten(brand).map(([path, value]) => ({
  path: path.join("."),
  name: cssName(path),
  value,
}));
const byPath = new Map(primitives.map((p) => [p.path, p]));

function hexToRgb(hex) {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/**
 * Resolve one theme value. `{path}` becomes var(--sl-…) in CSS, so a hue
 * change in brand.css reaches the theme with no rebuild of the consumer;
 * `{path/alpha}` has to be baked, because var() cannot take an alpha.
 * Returns both forms: `css` for the stylesheet, `literal` for the guard.
 */
export function resolve(value, where) {
  const m = /^\{([^}/]+)(?:\/([\d.]+))?\}$/.exec(value);
  if (!m) {
    if (value.includes("{")) throw new Error(`${where}: references must be the whole value, got ${value}`);
    return { css: value, literal: value };
  }
  const prim = byPath.get(m[1]);
  if (!prim) throw new Error(`${where}: no brand token "${m[1]}"`);
  if (m[2] === undefined) return { css: `var(${prim.name})`, literal: prim.value };
  const [r, g, b] = hexToRgb(prim.value);
  const rgba = `rgba(${r}, ${g}, ${b}, ${m[2]})`;
  return { css: rgba, literal: rgba };
}

function brandCss() {
  const lines = primitives.map((p) => `  ${p.name}: ${p.value};`);
  return `/* ${HEADER} */\n:root {\n${lines.join("\n")}\n}\n`;
}

function themeCss(theme) {
  const out = [`/* ${HEADER} */`, `/* Theme "${theme.id}". Import after @skylimit/brand/brand.css. */`];
  theme.blocks.forEach((block, i) => {
    const decls = Object.entries(block.vars).map(([name, value]) => {
      // A theme name in the --sl- namespace would shadow the primitive it
      // points at and resolve to itself, which browsers treat as unset.
      if (name.startsWith("--sl-")) throw new Error(`${theme.id}[${i}]: ${name} is in the brand namespace`);
      return `${name}: ${resolve(value, `${theme.id}[${i}] ${name}`).css};`;
    });
    const indent = block.media ? "    " : "  ";
    const rule = `${block.media ? "  " : ""}${block.selector} {\n${decls.map((d) => indent + d).join("\n")}\n${block.media ? "  " : ""}}`;
    out.push(block.media ? `@media ${block.media} {\n${rule}\n}` : rule);
  });
  return out.join("\n") + "\n";
}

/** Brand hues as Tailwind colours: sl-navy-800, sl-mint-500 … */
function colorTree() {
  const tree = {};
  for (const [path, value] of Object.entries(brand.color)) tree[path] = value;
  return tree;
}

function tailwindV3() {
  // Hex rather than var() for the sl-* scale so opacity modifiers (bg-sl-mint-500/20) work.
  const preset = {
    theme: {
      extend: {
        colors: {
          sl: colorTree(),
          theme: {
            bg: "var(--theme-bg)",
            "bg-dark": "var(--theme-bg-dark)",
            accent: "var(--theme-accent)",
            "accent-dim": "var(--theme-accent-dim)",
            "text-main": "var(--theme-text-main)",
            "text-muted": "var(--theme-text-muted)",
            border: "var(--theme-border)",
          },
          success: "var(--color-success)",
          "white-dim": "var(--color-white-dim)",
          "white-subtle": "var(--color-white-subtle)",
        },
        // The face itself is the app's to load (next/font in Next apps), which
        // sets --font-*; the brand stack is the fallback when it has not.
        fontFamily: {
          display: [`var(--font-display, ${brand.font.display})`],
          mono: [`var(--font-mono, ${brand.font.mono})`],
          stencil: [`var(--font-stencil, ${brand.font.stencil})`],
        },
        maxWidth: { content: "var(--max-width)" },
        height: { header: "var(--header-height)" },
        fontSize: {
          "hero-fluid": [brand.text.hero, { lineHeight: "1.1" }],
          "section-fluid": [brand.text.section, { lineHeight: "1" }],
        },
        transitionDuration: { DEFAULT: brand.motion.duration },
      },
    },
  };
  return `// ${HEADER}\n// Tailwind 3 preset: \`presets: [require("@skylimit/brand/tailwind-v3")]\`.\nmodule.exports = ${JSON.stringify(preset, null, 2)};\n`;
}

function tailwindV4() {
  const lines = primitives
    .filter((p) => p.path.startsWith("color."))
    .map((p) => `  --color-sl-${p.name.slice(5)}: var(${p.name});`);
  return `/* ${HEADER} */\n/* Tailwind 4: \`@import "@skylimit/brand/tailwind-v4.css";\` after "tailwindcss", plus brand.css for the values. */\n@theme inline {\n${lines.join("\n")}\n}\n`;
}

function tokensTs() {
  const themesOut = Object.fromEntries(
    themes.map((t) => [
      t.id,
      t.blocks.map((b) => ({
        selector: b.selector,
        ...(b.media ? { media: b.media } : {}),
        vars: Object.fromEntries(Object.entries(b.vars).map(([k, v]) => [k, resolve(v, t.id).literal])),
      })),
    ]),
  );
  return `// ${HEADER}\n\nexport const brand = ${JSON.stringify(
    Object.fromEntries(Object.entries(brand).filter(([k]) => !k.startsWith("$"))),
    null,
    2,
  )} as const;\n\nexport const themes = ${JSON.stringify(themesOut, null, 2)} as const;\n`;
}

export const outputs = {
  "brand.css": brandCss(),
  ...Object.fromEntries(themes.map((t) => [t.file, themeCss(t)])),
  "tailwind-v3.cjs": tailwindV3(),
  "tailwind-v4.css": tailwindV4(),
  "src/tokens.ts": tokensTs(),
};

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const check = process.argv.includes("--check");
  let stale = 0;
  for (const [file, content] of Object.entries(outputs)) {
    const path = join(root, file);
    const current = existsSync(path) ? readFileSync(path, "utf8").replace(/\r\n/g, "\n") : null;
    if (current === content) continue;
    if (check) {
      console.error(`stale: ${file}`);
      stale++;
    } else {
      writeFileSync(path, content);
      console.log(`wrote ${file}`);
    }
  }
  if (stale) {
    console.error("Run `npm run build` and commit the result.");
    process.exit(1);
  }
}
